<?= $this->extend('layouts/tenant_admin') ?><?= $this->section('content') ?><header class="page-head"><p class="eyebrow">Identity and authority</p><h1>Access administration</h1><p>Shield owns primary groups. This page manages permanent tenant membership lifecycle and operational responsibilities.</p></header><?= $this->include('tenant/admin/_messages') ?>
<section class="panel"><h2>Tenant accounts</h2><?php if($memberships===[]):?><div class="empty">No tenant accounts have been provisioned.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Account label</th><th>Status</th><th>Lifecycle action</th></tr></thead><tbody><?php foreach($memberships as $member):?><tr><td><strong><?= esc($member['membership_label'] ?? 'Tenant account') ?></strong></td><td><span class="badge"><?= esc($member['status']) ?></span></td><td><form class="compact-form" method="post" action="<?= site_url('tenant/admin/access/memberships/'.$member['id'].'/lifecycle') ?>"><?= csrf_field() ?><select name="status" aria-label="New lifecycle status"><option value="active">Active</option><option value="suspended">Suspended</option><option value="revoked">Revoked</option></select><input name="reason" required minlength="10" placeholder="Reason for change"><button>Apply</button></form></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<div class="split-grid"><section class="panel"><h2>Operational authorities</h2><form method="post" action="<?= site_url('tenant/admin/access/authorities') ?>"><?= csrf_field() ?><label>Authority code<input name="code" placeholder="website.content.edit" required></label><label>Name<input name="name" required></label><label>Description<textarea name="description"></textarea></label><button>Create authority</button></form><?= view('tenant/admin/_records',['records'=>$authorities,'primary'=>'name','secondary'=>'code']) ?></section>
<section class="panel"><h2>Grant responsibility</h2><?php if($memberships===[]||$authorities===[]):?><div class="empty">Create an authority and provision a tenant account before granting responsibility.</div><?php else:?><form method="post" action="<?= site_url('tenant/admin/access/grants') ?>"><?= csrf_field() ?><label>Tenant account<select name="membership_id" required><?php foreach($memberships as $member):if($member['status']!=='active')continue;?><option value="<?= $member['id'] ?>"><?= esc($member['membership_label']??'Tenant account') ?></option><?php endforeach?></select></label><label>Authority<select name="authority_id" required><?php foreach($authorities as $authority):?><option value="<?= $authority['id'] ?>"><?= esc($authority['name'].' · '.$authority['code']) ?></option><?php endforeach?></select></label><button>Grant authority</button></form><?php endif?><p class="muted"><?= count($grants) ?> active grant record(s).</p></section></div>
<div class="notice"><strong>Account provisioning boundary:</strong> primary broad groups and new credentials must be created through the approved tenant-aware Shield provider. This interface deliberately does not ask administrators for raw user IDs or expose the retired duplicate IAM group writer.</div>
<?= $this->endSection() ?>
